import { PeriodNav, Card } from "march/ui"

// ayın evreleri: oklar bir evre ilerler ya da geri gider, ortada evrenin kendisi (title bir işlev: canlı okunur);
// "Bu gece" bugünkü evreye döner
const phases = ["🌑 Yeni ay", "🌒 Hilal", "🌓 İlk dördün", "🌔 Şişkin ay", "🌕 Dolunay", "🌖 Azalan ay", "🌗 Son dördün", "🌘 Son hilal"]
const tonight = 4

export function MoonPhases() {
  let $phase = tonight
  const step = (d: number) => $phase = ($phase + d + phases.length) % phases.length
  return <Card m:theme="night">
    <div sx={{ flex: ["col", "center"], gap: 3 }}>
      <PeriodNav title={() => phases[$phase]} onPrev={() => step(-1)} onNext={() => step(1)} onToday={() => $phase = tonight}
        today="Bu gece" m:color="brand-purple" labels={{ group: "Ay evresi", previous: "Önceki evre", next: "Sonraki evre" }} />
      <span sx={{ text: "sm", color: "muted" }}>{$phase === tonight ? "Bu gece gökyüzünde" : `Bu geceden ${($phase - tonight + phases.length) % phases.length} evre sonra`}</span>
    </div>
  </Card>
}

import { PeriodNav, Card, Progress } from "march/ui"

// aylık bütçe: oklar ayı değiştirir (veri yalnız son altı ay için: uçlarda ok kapanır), "Bu ay" bugüne döner;
// ayın geliri, gideri ve harcanan payı. title bir işlev: PeriodNav onu canlı okur
const now = new Date()
const monthName = (offset: number) => new Intl.DateTimeFormat("tr", { month: "long", year: "numeric" }).format(new Date(now.getFullYear(), now.getMonth() + offset, 1))
// her ayın gideri (gerçekte bir query() olurdu)
const spent = (offset: number) => 18000 + ((Math.abs(offset) * 37 + 5) % 9) * 1400
const income = 32000
const tl = (n: number) => new Intl.NumberFormat("tr", { style: "currency", currency: "TRY", maximumFractionDigits: 0 }).format(n)

export function MonthlyBudget() {
  let $offset = 0
  return <Card title="Bütçem">
    <div sx={{ flex: "col", gap: 3 }}>
      <PeriodNav title={() => monthName($offset)} onPrev={() => $offset--} onNext={() => $offset++} onToday={() => $offset = 0} today="Bu ay"
        prevDisabled={$offset <= -5} nextDisabled={$offset >= 0} labels={{ group: "Ay", previous: "Önceki ay", next: "Sonraki ay" }} />
      <div sx={{ flex: ["row", "between"] }}>
        <span>{`Gelir: ${tl(income)}`}</span>
        <span sx={{ color: "danger" }}>{`Gider: ${tl(spent($offset))}`}</span>
        <span sx={{ text: "bold", color: "success" }}>{`Kalan: ${tl(income - spent($offset))}`}</span>
      </div>
      <Progress value={Math.round((spent($offset) / income) * 100)} label="Harcanan pay" />
    </div>
  </Card>
}

import { PeriodNav, Card } from "march/ui"
import { arrowLeft, arrowRight } from "march/icons"

// PeriodNav'ın bütün özellikleri bir arada: onPrev, onNext, onToday, today (kendi metni ya da false), title (ya da
// children), labels (group, previous, today, next), prevIcon, nextIcon, arrows, prevDisabled, nextDisabled, rtl,
// attached, size, partClass, class ve renk (m:color)
const now = new Date()
const monthName = (offset: number) => new Intl.DateTimeFormat("tr", { month: "long", year: "numeric" }).format(new Date(now.getFullYear(), now.getMonth() + offset, 1))

// bir sıra: adı solda, gezinme sağda
const Row = (props: { title: string; children?: unknown }) => <div sx={{ flex: ["row", "between"], gap: 3 }}>
  <span sx={{ text: "sm", color: "muted" }}>{props.title}</span>
  {props.children}
</div>

export function PeriodNavLab() {
  let $week = 0
  let $month = 0
  let $page = 1
  let $rtl = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Row title={`Bitişik, küçük (hafta ${$week >= 0 ? "+" : ""}${$week})`}>
      <PeriodNav onPrev={() => $week--} onNext={() => $week++} onToday={() => $week = 0} attached size="sm"
        labels={{ group: "Hafta seçici", previous: "Önceki hafta", today: "Bu hafta", next: "Sonraki hafta" }} />
    </Row>
    <Row title="Başlıklı, kendi ikonlar ve bugün metni, turuncu">
      <PeriodNav title={() => monthName($month)} onPrev={() => $month--} onNext={() => $month++} onToday={() => $month = 0}
        today="● Şimdi" prevIcon={arrowLeft} nextIcon={arrowRight} m:color="brand-orange" class="lab-month"
        partClass={{ prev: "lab-prev", next: "lab-next", today: "lab-today", title: "lab-title" }}
        labels={{ group: "Ay seçici", previous: () => "Önceki ay", next: () => "Sonraki ay" }} />
    </Row>
    <Row title="Sınırlı, başlık children, bugün yok (today={false})">
      <PeriodNav onPrev={() => $page--} onNext={() => $page++} onToday={() => $page = 1} today={false} attached={false}
        prevDisabled={$page <= 1} nextDisabled={$page >= 3} labels={{ group: "Sayfa seçici", previous: "Geri sayfa", next: "İleri sayfa" }}>
        {() => `Sayfa ${$page} / 3`}
      </PeriodNav>
    </Row>
    <Card m:theme="night">
      <Row title="Sağdan sola (rtl) ve oksuz (arrows={false})">
        <PeriodNav title="RTL" rtl onPrev={() => $rtl--} onNext={() => $rtl++} labels={{ group: "Sağdan sola" }} />
        <PeriodNav title={() => `Adım ${$rtl}`} arrows={false} onPrev={() => {}} onNext={() => {}} onToday={() => $rtl = 0}
          labels={{ group: "Oksuz dönem", today: "Sıfırla" }} />
      </Row>
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PeriodNavLab } from "./PeriodNavLab.tsx"

// PeriodNavLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Oklar onPrev / onNext'i, bugün düğmesi onToday'i çağırır; labels adları verir", async () => {
  const s = renderTest(() => <PeriodNavLab />)
  await s.click("Sonraki hafta")
  await s.click("Sonraki hafta")
  expect(s.sees("hafta +2")).toBe(true)
  await s.click("Bu hafta")
  expect(s.sees("hafta +0")).toBe(true)
  expect(s.find("Hafta seçici")?.getAttribute("role")).toBe("group")
})

test("title okların arasında ve canlı; partClass ve class parçalarda", async () => {
  const s = renderTest(() => <PeriodNavLab />)
  const title = s.get(".lab-month .lab-title")
  const before = title?.textContent
  await s.click("Sonraki ay")
  expect(title?.textContent).not.toBe(before)
  expect(s.find("Önceki ay")?.classList.contains("lab-prev")).toBe(true)
  expect(s.find("● Şimdi")?.closest("button")?.classList.contains("lab-today")).toBe(true)
})

test("prevDisabled / nextDisabled uçlarda okları kapatır; today={false} düğmeyi kaldırır", async () => {
  const s = renderTest(() => <PeriodNavLab />)
  expect(s.find("Geri sayfa")?.hasAttribute("disabled")).toBe(true)
  await s.click("İleri sayfa")
  await s.click("İleri sayfa")
  expect(s.sees("Sayfa 3 / 3")).toBe(true)
  expect(s.find("İleri sayfa")?.hasAttribute("disabled")).toBe(true)
  expect(s.find("Sayfa seçici")?.querySelectorAll("button").length).toBe(2)
})

test("arrows={false} okları kaldırır, bugün düğmesi kalır", () => {
  const s = renderTest(() => <PeriodNavLab />)
  expect(s.find("Oksuz dönem")?.querySelectorAll("button").length).toBe(1)
  expect(s.find("Sıfırla")).not.toBe(null)
})
